import { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import jaedenPhoto from './assets/jaeden-callender.png';
import davidPhoto from './assets/david-prudhomme.png';

/* ─────────────────────────────────────────────────────────────
   APEX — Nuvion Solutions  |  Mobile-first, single-file React
───────────────────────────────────────────────────────────── */

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800;1,400&display=swap');

:root{
  --bg:#07090F;--surface:#0D1221;--surface2:#111829;
  --border:rgba(79,110,247,0.12);
  --primary:#4F6EF7;--primary2:#3B5BDB;
  --cyan:#00DCFF;--violet:#A78BFA;
  --text:#F1F5F9;--muted:#8B99B5;--dim:#404860;
  --font:'Plus Jakarta Sans',system-ui,sans-serif;
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;scroll-padding-top:30px}
*[id]{scroll-margin-top:30px}
body{font-family:var(--font);background:var(--bg);color:var(--text);overflow-x:hidden;-webkit-font-smoothing:antialiased}

@keyframes fadeUp{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:translateY(0)}}
@keyframes floatA{0%,100%{transform:translateY(0) rotate(0deg)}40%{transform:translateY(-22px) rotate(1.5deg)}70%{transform:translateY(10px) rotate(-1deg)}}
@keyframes floatB{0%,100%{transform:translateY(0) rotate(0deg)}30%{transform:translateY(14px) rotate(-2deg)}70%{transform:translateY(-18px) rotate(1deg)}}
@keyframes pulseRing{0%{transform:scale(.95);box-shadow:0 0 0 0 rgba(0,220,255,.5)}70%{transform:scale(1);box-shadow:0 0 0 14px rgba(0,220,255,0)}100%{transform:scale(.95);box-shadow:0 0 0 0 rgba(0,220,255,0)}}
@keyframes shimmer{0%{background-position:220% center}100%{background-position:-220% center}}
@keyframes marquee{0%{transform:translateX(0)}100%{transform:translateX(-50%)}}

.reveal{opacity:0;transform:translateY(28px);transition:opacity .65s ease,transform .65s ease}
.reveal.vis{opacity:1;transform:translateY(0)}
.d1{transition-delay:.08s}.d2{transition-delay:.16s}.d3{transition-delay:.24s}
.d4{transition-delay:.32s}.d5{transition-delay:.4s}.d6{transition-delay:.48s}

.container{width:100%;max-width:1200px;margin:0 auto;padding:0 20px}
@media(min-width:768px){.container{padding:0 32px}}
@media(min-width:1200px){.container{padding:0 44px}}

.grad{background:linear-gradient(130deg,var(--cyan) 0%,var(--primary) 48%,var(--violet) 100%);background-size:220% auto;-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;animation:shimmer 6s linear infinite}

.btn{display:inline-flex;align-items:center;gap:8px;padding:13px 28px;border-radius:10px;font-family:var(--font);font-size:.95rem;font-weight:700;cursor:pointer;transition:all .25s ease;text-decoration:none;border:none;outline:none;white-space:nowrap;line-height:1}
.btn-primary{background:linear-gradient(135deg,var(--primary) 0%,var(--primary2) 100%);color:#fff;box-shadow:0 4px 22px rgba(79,110,247,.38)}
.btn-primary:hover{transform:translateY(-2px);box-shadow:0 8px 32px rgba(79,110,247,.55)}
.btn-ghost{background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.1);color:var(--text)}
.btn-ghost:hover{border-color:rgba(79,110,247,.4);background:rgba(79,110,247,.07);color:#fff}
.btn-cyan{background:linear-gradient(135deg,var(--cyan) 0%,#00AACC 100%);color:#020E14;font-weight:800;box-shadow:0 4px 22px rgba(0,220,255,.32)}
.btn-cyan:hover{transform:translateY(-2px);box-shadow:0 8px 32px rgba(0,220,255,.48)}
.btn-lg{padding:16px 38px;font-size:1.05rem}

/* NAV */
.nav{position:fixed;top:0;left:0;right:0;z-index:200;padding:0 20px;transition:background .3s,border-color .3s}
.nav.scrolled{background:rgba(7,9,15,.88);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid rgba(79,110,247,.1)}
.nav-inner{display:flex;align-items:center;justify-content:space-between;height:76px;max-width:1200px;margin:0 auto}
.nav-logo{display:flex;align-items:center;gap:10px;font-weight:800;font-size:1.18rem;color:var(--text);text-decoration:none}
.nav-mark{width:34px;height:34px;border-radius:9px;background:linear-gradient(135deg,var(--primary),var(--cyan));display:flex;align-items:center;justify-content:center;font-size:.95rem;font-weight:900;color:#fff;box-shadow:0 2px 14px rgba(79,110,247,.45);flex-shrink:0}
.nav-links{display:none;list-style:none;gap:2px}
@media(min-width:900px){.nav-links{display:flex}}
.nav-link{padding:8px 14px;border-radius:8px;font-size:.88rem;font-weight:500;color:var(--muted);text-decoration:none;transition:all .2s}
.nav-link:hover{color:var(--text);background:rgba(255,255,255,.05)}
.nav-cta{display:none}
@media(min-width:900px){.nav-cta{display:flex}}
.nav-burger{display:flex;flex-direction:column;gap:5px;padding:8px;cursor:pointer;border:none;background:transparent;border-radius:6px;transition:background .2s}
@media(min-width:900px){.nav-burger{display:none}}
.nav-burger:hover{background:rgba(255,255,255,.06)}
.nav-burger span{display:block;width:22px;height:2px;background:var(--muted);border-radius:2px;transition:all .3s}
.nav-burger.open span:nth-child(1){transform:translateY(7px) rotate(45deg);background:var(--text)}
.nav-burger.open span:nth-child(2){opacity:0;transform:scaleX(0)}
.nav-burger.open span:nth-child(3){transform:translateY(-7px) rotate(-45deg);background:var(--text)}
.mobile-menu{position:fixed;top:76px;left:0;right:0;bottom:0;background:var(--bg);z-index:199;display:flex;flex-direction:column;padding:28px 24px;transform:translateX(100%);transition:transform .35s cubic-bezier(.4,0,.2,1);border-top:1px solid rgba(79,110,247,.08);overflow-y:auto}
.mobile-menu.open{transform:translateX(0)}
.mobile-menu a{display:block;padding:16px 0;font-size:1.15rem;font-weight:600;color:var(--text);text-decoration:none;border-bottom:1px solid rgba(255,255,255,.04);transition:color .2s}
.mobile-menu a:hover{color:var(--cyan)}
.mobile-menu .btn{margin-top:28px;width:100%;justify-content:center;padding:16px 28px}

/* HERO */
.hero{position:relative;overflow:hidden;min-height:100svh;display:flex;align-items:center;padding:120px 20px 80px}
.hero-bg{position:absolute;inset:0;overflow:hidden;z-index:0}
.orb{position:absolute;border-radius:50%;filter:blur(88px);opacity:.42}
.orb-1{width:520px;height:520px;top:-120px;left:-160px;background:radial-gradient(circle,rgba(79,110,247,.75),rgba(79,110,247,0) 68%);animation:floatA 15s ease-in-out infinite}
.orb-2{width:420px;height:420px;top:80px;right:-110px;background:radial-gradient(circle,rgba(0,220,255,.65),rgba(0,220,255,0) 68%);animation:floatB 19s ease-in-out infinite}
.orb-3{width:320px;height:320px;bottom:-60px;left:32%;background:radial-gradient(circle,rgba(167,139,250,.55),rgba(167,139,250,0) 68%);animation:floatA 23s ease-in-out infinite;animation-delay:-9s}
.hero-grid{position:absolute;inset:0;background-image:linear-gradient(rgba(79,110,247,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(79,110,247,.045) 1px,transparent 1px);background-size:52px 52px;mask-image:radial-gradient(ellipse 80% 80% at 50% 40%,black,transparent);-webkit-mask-image:radial-gradient(ellipse 80% 80% at 50% 40%,black,transparent)}
.hero-inner{position:relative;z-index:1;max-width:1200px;margin:0 auto;width:100%}
.hero-badge{display:inline-flex;align-items:center;gap:8px;padding:7px 16px;border-radius:100px;background:rgba(79,110,247,.1);border:1px solid rgba(79,110,247,.25);font-size:.75rem;font-weight:700;color:var(--cyan);letter-spacing:.1em;text-transform:uppercase;margin-bottom:28px;animation:fadeUp .55s ease both}
.badge-dot{width:6px;height:6px;border-radius:50%;background:var(--cyan);animation:pulseRing 2.2s ease infinite}
.hero-h1{font-size:clamp(2.7rem,7.5vw,5.4rem);font-weight:800;line-height:1.07;letter-spacing:-.035em;color:var(--text);margin-bottom:24px;animation:fadeUp .6s ease both .08s}
.hero-sub{font-size:clamp(.98rem,2.2vw,1.18rem);font-weight:400;color:var(--muted);line-height:1.68;max-width:560px;margin-bottom:40px;animation:fadeUp .6s ease both .16s}
.hero-btns{display:flex;flex-wrap:wrap;gap:14px;margin-bottom:56px;animation:fadeUp .6s ease both .24s}
.hero-proof{display:flex;flex-wrap:wrap;gap:22px;animation:fadeUp .6s ease both .32s}
.proof-item{display:flex;align-items:center;gap:7px;font-size:.83rem;color:var(--muted)}
@media(max-width:599px){.hero-btns{flex-direction:column}.hero-btns .btn{width:100%;justify-content:center}}

/* STRIP */
.strip{position:relative;padding:16px 0;overflow:hidden;border-top:1px solid rgba(79,110,247,.1);border-bottom:1px solid rgba(79,110,247,.1);background:rgba(13,18,33,.7)}
.strip-track{display:flex;animation:marquee 26s linear infinite;width:max-content}
.strip-item{padding:0 38px;font-size:.75rem;font-weight:700;letter-spacing:.15em;text-transform:uppercase;color:var(--dim);display:flex;align-items:center;gap:12px;flex-shrink:0;white-space:nowrap}
.strip-dot{width:4px;height:4px;border-radius:50%;background:var(--primary);flex-shrink:0}

/* SECTION BASE */
.section{padding:96px 20px}
@media(min-width:768px){.section{padding:120px 32px}}
.sec-label{display:inline-block;font-size:.72rem;font-weight:700;letter-spacing:.2em;text-transform:uppercase;color:var(--primary);margin-bottom:12px}
.sec-h2{font-size:clamp(1.9rem,4vw,3rem);font-weight:800;line-height:1.1;letter-spacing:-.028em;color:var(--text);margin-bottom:14px}
.sec-sub{font-size:.98rem;color:var(--muted);line-height:1.68;max-width:580px}
.sec-head{margin-bottom:56px}
.sec-head.center{text-align:center}
.sec-head.center .sec-sub{margin:0 auto}

/* SERVICES */
.svc-grid{display:grid;grid-template-columns:1fr;gap:18px}
@media(min-width:600px){.svc-grid{grid-template-columns:repeat(2,1fr)}}
@media(min-width:1000px){.svc-grid{grid-template-columns:repeat(3,1fr)}}
.svc-card{position:relative;overflow:hidden;padding:28px 28px 52px;background:var(--surface);border:1px solid var(--border);border-radius:16px;transition:transform .3s,border-color .3s,box-shadow .3s;cursor:pointer;text-decoration:none;display:block;color:inherit}
.svc-card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent,rgba(79,110,247,.7),rgba(0,220,255,.7),transparent);opacity:0;transition:opacity .3s}
.svc-card:hover{transform:translateY(-5px);border-color:rgba(79,110,247,.35);box-shadow:0 20px 50px rgba(0,0,0,.35),0 0 40px rgba(79,110,247,.07)}
.svc-card:hover::before{opacity:1}
.svc-icon{width:52px;height:52px;border-radius:13px;display:flex;align-items:center;justify-content:center;font-size:1.35rem;margin-bottom:20px;flex-shrink:0}
.svc-title{font-size:1.02rem;font-weight:700;color:var(--text);margin-bottom:10px;letter-spacing:-.01em}
.svc-desc{font-size:.875rem;color:var(--muted);line-height:1.62}
.svc-arrow{position:absolute;bottom:22px;right:22px;width:30px;height:30px;border-radius:8px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.06);display:flex;align-items:center;justify-content:center;color:var(--dim);font-size:.85rem;transition:all .2s}
.svc-card:hover .svc-arrow{background:rgba(79,110,247,.15);border-color:rgba(79,110,247,.3);color:var(--primary)}

/* HOW IT WORKS */
.hiw-bg{background:linear-gradient(180deg,var(--bg) 0%,rgba(13,18,33,.5) 50%,var(--bg) 100%)}
.hiw-steps{display:grid;grid-template-columns:1fr;gap:40px;position:relative}
@media(min-width:900px){.hiw-steps{grid-template-columns:repeat(3,1fr)}}
.hiw-line{display:none;position:absolute;top:50px;left:calc(33.33% + 50px);right:calc(33.33% + 50px);height:1px;background:linear-gradient(90deg,rgba(79,110,247,.5),rgba(0,220,255,.5))}
@media(min-width:900px){.hiw-line{display:block}}
.hiw-step{display:flex;flex-direction:column;align-items:center;text-align:center}
.hiw-num{width:76px;height:76px;border-radius:50%;background:linear-gradient(135deg,var(--primary),var(--primary2));display:flex;align-items:center;justify-content:center;font-size:1.5rem;font-weight:800;color:#fff;margin-bottom:24px;box-shadow:0 4px 26px rgba(79,110,247,.38);position:relative;z-index:1;flex-shrink:0}
.hiw-title{font-size:1.1rem;font-weight:700;color:var(--text);margin-bottom:12px;letter-spacing:-.015em}
.hiw-desc{font-size:.875rem;color:var(--muted);line-height:1.65;max-width:260px;margin:0 auto}

/* STATS */
.stats-wrap{padding:0 20px 96px}
@media(min-width:768px){.stats-wrap{padding:0 32px 120px}}
.stats-card{max-width:1200px;margin:0 auto;background:var(--surface);border:1px solid var(--border);border-radius:24px;padding:56px 40px;display:grid;grid-template-columns:1fr;gap:40px;position:relative;overflow:hidden}
@media(min-width:600px){.stats-card{grid-template-columns:repeat(2,1fr)}}
@media(min-width:1000px){.stats-card{grid-template-columns:repeat(4,1fr)}}
.stats-card::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--primary) 20%,var(--cyan) 50%,var(--violet) 80%,transparent)}
.stat{text-align:center}
.stat-n{font-size:clamp(2.4rem,5vw,3.5rem);font-weight:800;letter-spacing:-.045em;background:linear-gradient(130deg,var(--cyan),var(--primary) 55%,var(--violet));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;line-height:1.1;margin-bottom:8px}
.stat-l{font-size:.88rem;color:var(--muted);font-weight:500}
@media(max-width:599px){.stats-card{padding:40px 24px;gap:28px}}

/* WHY NUVION */
.why-grid{display:grid;grid-template-columns:1fr;gap:24px;align-items:start}
@media(min-width:600px){.why-grid{gap:32px}}
@media(min-width:900px){.why-grid{grid-template-columns:1fr 1fr;gap:64px;align-items:center}}
.why-feats{display:flex;flex-direction:column;gap:16px;order:2}
@media(min-width:900px){.why-feats{order:1}}
.why-feat{display:flex;gap:16px;padding:20px;background:var(--surface);border:1px solid var(--border);border-radius:14px;transition:border-color .25s,transform .25s}
.why-feat:hover{border-color:rgba(79,110,247,.3);transform:translateX(4px)}
.why-feat-icon{width:44px;height:44px;border-radius:11px;background:rgba(79,110,247,.1);border:1px solid rgba(79,110,247,.2);display:flex;align-items:center;justify-content:center;font-size:1.1rem;flex-shrink:0}
.why-feat-title{font-size:.92rem;font-weight:700;color:var(--text);margin-bottom:4px}
.why-feat-desc{font-size:.825rem;color:var(--muted);line-height:1.55}
.why-visual{display:flex;align-items:center;justify-content:center;order:1;width:100%}
@media(min-width:900px){.why-visual{order:2;width:auto}}
.w-stack{position:relative;width:100%;max-width:380px;aspect-ratio:4/3}
.w-bg{position:absolute;inset:0;background:var(--surface2);border:1px solid var(--border);border-radius:20px;transform:rotate(4deg)}
.w-mid{position:absolute;inset:10px;background:var(--surface);border:1px solid rgba(79,110,247,.14);border-radius:16px;transform:rotate(-2.5deg)}
.w-front{position:absolute;inset:18px;background:linear-gradient(135deg,var(--surface),#0D1828);border:1px solid rgba(79,110,247,.22);border-radius:14px;padding:26px;display:flex;flex-direction:column;gap:18px;justify-content:center}
.w-badge{display:inline-flex;align-items:center;gap:6px;padding:5px 12px;background:rgba(0,220,255,.08);border:1px solid rgba(0,220,255,.2);border-radius:100px;font-size:.7rem;font-weight:700;color:var(--cyan);letter-spacing:.08em;text-transform:uppercase;width:fit-content}
.w-metric{font-size:2.4rem;font-weight:800;background:linear-gradient(130deg,var(--cyan),var(--primary));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;letter-spacing:-.04em}
.w-lbl{font-size:.8rem;color:var(--muted);margin-top:-10px}
.w-bar{height:6px;border-radius:3px;background:rgba(255,255,255,.06);overflow:hidden;margin-top:4px}
.w-fill{height:100%;border-radius:3px;background:linear-gradient(90deg,var(--primary),var(--cyan));width:78%}
.w-sub{font-size:.74rem;color:var(--dim)}

/* TESTIMONIALS */
.testi-outer{overflow:hidden}
.testi-track{display:flex;transition:transform .5s cubic-bezier(.4,0,.2,1)}
.testi-slide{flex-shrink:0;width:100%;padding:0 20px}
@media(min-width:768px){.testi-slide{padding:0 40px}}
.testi-card{max-width:780px;margin:0 auto;background:var(--surface);border:1px solid var(--border);border-radius:22px;padding:44px;position:relative;overflow:hidden}
.testi-card::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--cyan),transparent)}
.testi-glow{position:absolute;bottom:-80px;right:-80px;width:250px;height:250px;background:radial-gradient(circle,rgba(79,110,247,.08),transparent 70%);pointer-events:none}
.testi-q{font-size:3rem;color:var(--primary);line-height:1;margin-bottom:16px;font-family:Georgia,serif;opacity:.7}
.testi-text{font-size:1.05rem;color:var(--text);line-height:1.72;font-style:italic;margin-bottom:28px}
.testi-footer{display:flex;align-items:center;flex-wrap:wrap;gap:14px}
.testi-av{width:46px;height:46px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;color:#fff;font-size:.95rem;flex-shrink:0}
.testi-name{font-weight:700;color:var(--text);font-size:.92rem}
.testi-role{font-size:.78rem;color:var(--muted)}
.testi-stars{margin-left:auto;color:#FFC645;font-size:.85rem;letter-spacing:1px}
.testi-nav{display:flex;align-items:center;justify-content:center;gap:14px;margin-top:36px}
.testi-dot{width:8px;height:8px;border-radius:4px;background:var(--dim);cursor:pointer;transition:all .3s;border:none;outline:none}
.testi-dot.on{width:24px;background:var(--primary)}
.testi-btn{width:40px;height:40px;border-radius:10px;background:var(--surface);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;color:var(--muted);cursor:pointer;transition:all .2s;font-size:1rem}
.testi-btn:hover{border-color:rgba(79,110,247,.4);color:var(--text);background:rgba(79,110,247,.08)}
@media(max-width:599px){.testi-card{padding:28px 20px}.testi-stars{display:none}}

/* TEAM */
.team-grid{display:grid;grid-template-columns:1fr;gap:28px;max-width:820px;margin:0 auto}
@media(min-width:600px){.team-grid{grid-template-columns:repeat(2,1fr)}}
.team-card{background:var(--surface);border:1px solid var(--border);border-radius:20px;overflow:hidden;transition:transform .3s,border-color .3s,box-shadow .3s}
.team-card:hover{transform:translateY(-5px);border-color:rgba(79,110,247,.3);box-shadow:0 20px 50px rgba(0,0,0,.28)}
.team-photo{width:100%;aspect-ratio:3/4;object-fit:cover;object-position:center top;display:block;background:var(--surface2)}
.team-ph{width:100%;aspect-ratio:4/3;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#0D1221,#131929);font-size:3rem;color:var(--dim)}
.team-body{padding:24px}
.team-name{font-size:1.12rem;font-weight:800;color:var(--text);margin-bottom:4px;letter-spacing:-.015em}
.team-role{font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.12em;color:var(--cyan);margin-bottom:12px}
.team-bio{font-size:.85rem;color:var(--muted);line-height:1.62}

/* CTA */
.cta-wrap{padding:0 20px 96px}
@media(min-width:768px){.cta-wrap{padding:0 32px 120px}}
.cta-card{max-width:940px;margin:0 auto;background:linear-gradient(135deg,#0D1221,#0F1A2E);border:1px solid rgba(79,110,247,.2);border-radius:28px;padding:76px 48px;text-align:center;position:relative;overflow:hidden}
.cta-card::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--primary) 25%,var(--cyan) 50%,var(--primary) 75%,transparent)}
.cta-card::after{content:'';position:absolute;width:600px;height:600px;border-radius:50%;bottom:-320px;right:-220px;background:radial-gradient(circle,rgba(79,110,247,.07),transparent 70%);pointer-events:none}
.cta-h2{font-size:clamp(2rem,4vw,3.2rem);font-weight:800;letter-spacing:-.03em;color:var(--text);margin-bottom:16px;line-height:1.1}
.cta-sub{font-size:1rem;color:var(--muted);line-height:1.68;max-width:520px;margin:0 auto 40px}
.cta-row{display:flex;flex-wrap:wrap;gap:14px;justify-content:center}
.cta-guar{margin-top:26px;font-size:.8rem;color:var(--dim);display:flex;align-items:center;justify-content:center;gap:7px}
@media(max-width:599px){.cta-card{padding:48px 22px}.cta-row{flex-direction:column;align-items:stretch}.cta-row .btn{width:100%;justify-content:center}}

/* FOOTER */
.footer{border-top:1px solid rgba(79,110,247,.08);padding:64px 20px 40px}
.footer-inner{max-width:1200px;margin:0 auto;display:grid;grid-template-columns:1fr;gap:48px}
@media(min-width:768px){.footer-inner{grid-template-columns:2fr 1fr 1fr}}
.f-logo-row{display:flex;align-items:center;gap:10px;margin-bottom:12px}
.f-mark{width:32px;height:32px;border-radius:8px;background:linear-gradient(135deg,var(--primary),var(--cyan));display:flex;align-items:center;justify-content:center;font-weight:900;color:#fff;font-size:.9rem}
.f-brand{font-size:1.1rem;font-weight:800;color:var(--text)}
.f-tag{font-size:.85rem;color:var(--muted);line-height:1.65;margin-bottom:22px;max-width:280px}
.f-contact{display:flex;flex-direction:column;gap:8px}
.f-contact a{font-size:.83rem;color:var(--muted);text-decoration:none;transition:color .2s}
.f-contact a:hover{color:var(--cyan)}
.f-col-title{font-size:.72rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--text);margin-bottom:16px}
.f-links{list-style:none;display:flex;flex-direction:column;gap:10px}
.f-links a{font-size:.85rem;color:var(--muted);text-decoration:none;transition:color .2s}
.f-links a:hover{color:var(--text)}
.footer-bot{max-width:1200px;margin:36px auto 0;padding-top:22px;border-top:1px solid rgba(255,255,255,.04);display:flex;flex-wrap:wrap;gap:12px;justify-content:space-between;align-items:center}
.f-copy{font-size:.78rem;color:var(--dim)}
.f-leg{display:flex;gap:20px}
.f-leg a{font-size:.78rem;color:var(--dim);text-decoration:none;transition:color .2s}
.f-leg a:hover{color:var(--muted)}

svg{display:block}
a{color:inherit}
img{display:block;max-width:100%}
/* ── Card Deck ─────────────────────────────────────────────────── */
.deck-outer{display:flex;flex-direction:column;align-items:center;width:100%;max-width:100%;padding-bottom:52px}
@media(min-width:480px){.deck-outer{max-width:380px;padding-bottom:56px}}
.deck-wrap{position:relative;width:100%;height:240px;cursor:pointer;user-select:none;overflow:visible}
@media(min-width:480px){.deck-wrap{height:264px}}
.deck-card{position:absolute;inset:0;border-radius:18px;padding:20px;display:flex;flex-direction:column;gap:11px;justify-content:center;backface-visibility:hidden;-webkit-backface-visibility:hidden;will-change:transform}
@media(min-width:480px){.deck-card{padding:26px;gap:13px}}
.deck-hint{font-size:.72rem;color:var(--dim);margin-top:56px;display:flex;align-items:center;justify-content:center;gap:7px;letter-spacing:.05em;user-select:none;transition:color .2s}
@media(min-width:480px){.deck-hint{margin-top:60px}}
.deck-outer:hover .deck-hint{color:var(--muted)}

/* FAQ */
.faq-section{padding:96px 20px}
@media(min-width:768px){.faq-section{padding:120px 32px}}
.faq-list{max-width:780px;margin:0 auto;display:flex;flex-direction:column;gap:2px}
.faq-item{border:1px solid var(--border);border-radius:14px;overflow:hidden;background:var(--surface);transition:border-color .25s}
.faq-item.open{border-color:rgba(79,110,247,.35)}
.faq-q{width:100%;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:22px 24px;background:transparent;border:none;cursor:pointer;text-align:left;font-family:var(--font);font-size:.95rem;font-weight:600;color:var(--text);line-height:1.4;transition:color .2s}
.faq-q:hover{color:#fff}
.faq-chevron{flex-shrink:0;width:20px;height:20px;border-radius:6px;background:rgba(79,110,247,.1);border:1px solid rgba(79,110,247,.2);display:flex;align-items:center;justify-content:center;color:var(--primary);font-size:.75rem;transition:all .3s;line-height:1}
.faq-item.open .faq-chevron{background:rgba(79,110,247,.2);transform:rotate(180deg)}
.faq-a{max-height:0;overflow:hidden;transition:max-height .4s cubic-bezier(.4,0,.2,1),padding .3s}
.faq-item.open .faq-a{max-height:400px}
.faq-a-inner{padding:0 24px 22px;font-size:.875rem;color:var(--muted);line-height:1.72}
`;


