function Navbar() {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const fn = () => setScrolled(window.scrollY > 40);
    window.addEventListener('scroll', fn, { passive: true });
    return () => window.removeEventListener('scroll', fn);
  }, []);

  const links = [
    { href: '#services', label: 'Services' },
    { href: '#how-it-works', label: 'How It Works' },
    { href: '#why-us', label: 'Why Nuvion' },
    { href: '#team', label: 'Team' },
    { href: 'https://portfolio.nuvion-solutions.com', label: 'Portfolio', external: true },
    { href: '/audit', label: '🔍 Free Audit' },
  ];

  return (
    <>
      <nav className={`nav${scrolled ? ' scrolled' : ''}`}>
        <div className="nav-inner">
          <a href="#" className="nav-logo">
            <img src="data:image/png;base64," alt="Nuvion Solutions" style={{width:'150px',height:'auto',objectFit:'contain'}} />
          </a>
          <ul className="nav-links">
            {links.map(l => <li key={l.href}><a href={l.href} className="nav-link" {...(l.external ? { target: '_blank', rel: 'noopener noreferrer' } : {})}>{l.label}</a></li>)}
          </ul>
          <Link to="/book" className="btn btn-primary nav-cta" style={{ padding: '10px 22px', fontSize: '.88rem' }}>
            Get Started
          </Link>
          <button className={`nav-burger${open ? ' open' : ''}`} onClick={() => setOpen(o => !o)} aria-label="Menu">
            <span /><span /><span />
          </button>
        </div>
      </nav>
      <div className={`mobile-menu${open ? ' open' : ''}`} onClick={() => setOpen(false)}>
        {links.map(l => <a key={l.href} href={l.href} {...(l.external ? { target: '_blank', rel: 'noopener noreferrer' } : {})}>{l.label}</a>)}
        <Link to="/book" className="btn btn-cyan">Get Started →</Link>
      </div>
    </>
  );
}

