function WhyNuvion() {
  const feats = [
    { icon: '🎯', title: 'Built for Your Business Specifically', desc: 'No templates, no one-size-fits-all tools. Every system is custom-designed to fit your exact workflows and team.' },
    { icon: '⚡', title: 'Faster Time-to-Value', desc: 'Most clients see measurable results within 30 days. We move fast without sacrificing quality or reliability.' },
    { icon: '🔒', title: 'You Own Everything We Build', desc: "Your automation systems are yours. No proprietary lock-in, no monthly platform fees you can't escape." },
    { icon: '🤝', title: 'Ongoing Support Included', desc: "We don't disappear after launch. Every engagement includes support, monitoring, and optimization." },
  ];

  const DECK = [
    { badge: 'Lead Conversion',  metric: '9×',     label: 'Higher Conversion Rate',    bar: 78, note: 'Responding to leads within 5 min',  s1: 'Source: InsideSales.com',  s2: 'Harvard study',  accent: '#4F6EF7' },
    { badge: 'Time Savings',    metric: '20 hrs', label: 'Saved per week',            bar: 85, note: 'Avg. for SMBs using automation',     s1: 'Source: Zapier SMB Report', s2: '2024 benchmark', accent: '#00DCFF' },
    { badge: 'No-Shows',        metric: '−80%',   label: 'No-Show Rate Reduction',    bar: 80, note: 'With automated reminder sequences',  s1: 'Industry standard',        s2: 'All service sectors', accent: '#A78BFA' },
    { badge: 'Lead Generation', metric: '451%',   label: 'More Qualified Leads',      bar: 91, note: 'Businesses using lead nurturing',    s1: 'Source: Annuitas Group',   s2: 'B2B benchmark',  accent: '#34D399' },
  ];

  const n = DECK.length;
  const [front,    setFront]    = useState(0);
  const [exiting,  setExiting]  = useState(false);
  const [floatUp,  setFloatUp]  = useState(false);
  const [settling, setSettling] = useState(false);

  // JS-driven float — no CSS animation, so there is zero conflict with exit transition
  useEffect(() => {
    const t = setInterval(() => setFloatUp(v => !v), 2600);
    return () => clearInterval(t);
  }, []);

  // Give the newly-promoted card a fast spring transition before switching to slow float
  useEffect(() => {
    setSettling(true);
    const t = setTimeout(() => setSettling(false), 680);
    return () => clearTimeout(t);
  }, [front]);

  const handleClick = () => {
    if (exiting) return;
    setExiting(true);
    setTimeout(() => {
      setFront(f => (f + 1) % n);
      setExiting(false);
    }, 480);
  };

  const getPos = (i) => (i - front + n) % n;

  const getTransform = (pos, isExit) => {
    if (isExit)  return 'translateX(-140%) translateY(4px) rotate(-9deg) scale(0.9)';
    if (pos === 0) return `translateY(${floatUp ? -10 : 0}px) scale(1)`;
    if (pos === 1) return 'translateY(16px) rotate(4deg) scale(0.94)';
    if (pos === 2) return 'translateY(30px) rotate(7deg) scale(0.88)';
    return 'translateY(42px) rotate(10deg) scale(0.82)';
  };

  // Each card has ONE transition at any moment — no fighting
  const getTransition = (pos, isExit) => {
    if (isExit)  return 'transform 0.48s ease-in-out, opacity 0.38s ease 0.06s';
    if (pos === 0) return settling
      ? 'transform 0.62s cubic-bezier(0.22,1,0.36,1)'   // spring in from stack
      : 'transform 2.6s ease-in-out';                    // slow float
    return 'transform 0.62s cubic-bezier(0.22,1,0.36,1), opacity 0.62s ease';
  };

  return (
    <section id="why-us" className="section">
      <div className="container">
        <div className="sec-head" style={{ marginBottom: '40px' }}>
          <div className="sec-label reveal">Why Choose Us</div>
          <h2 className="sec-h2 reveal d1">Automation That<br /><span className="grad">Actually Works</span></h2>
          <p className="sec-sub reveal d2">
            We've seen what generic software promises. We deliver custom-built systems engineered around the specific problems your business faces every day.
          </p>
        </div>
        <div className="why-grid">
          <div className="why-feats">
            {feats.map((f, i) => (
              <div key={f.title} className={`why-feat reveal d${i + 1}`}>
                <div className="why-feat-icon">{f.icon}</div>
                <div>
                  <div className="why-feat-title">{f.title}</div>
                  <div className="why-feat-desc">{f.desc}</div>
                </div>
              </div>
            ))}
          </div>

          <div className="why-visual reveal d3">
            <div className="deck-outer">
              <div className="deck-wrap" onClick={handleClick}>
                {DECK.map((card, i) => {
                  const pos     = getPos(i);
                  const isFront = pos === 0;
                  const isExit  = isFront && exiting;

                  return (
                    <div
                      key={i}
                      style={{
                        position: 'absolute',
                        inset: 0,
                        borderRadius: '18px',
                        padding: 'clamp(18px,4vw,26px)',
                        display: 'flex',
                        flexDirection: 'column',
                        gap: '12px',
                        justifyContent: 'center',
                        backfaceVisibility: 'hidden',
                        WebkitBackfaceVisibility: 'hidden',
                        willChange: 'transform, opacity',
                        transform:  getTransform(pos, isExit),
                        opacity:    isExit ? 0 : pos === 3 ? 0.5 : 1,
                        zIndex:     n - pos,
                        transition: getTransition(pos, isExit),
                        background: 'linear-gradient(135deg,var(--surface) 0%,#0D1828 100%)',
                        border:     isFront && !exiting ? `1px solid ${card.accent}44` : '1px solid var(--border)',
                        boxShadow:  isFront && !exiting
                          ? `0 22px 60px rgba(0,0,0,0.5), 0 0 40px ${card.accent}1A`
                          : '0 4px 16px rgba(0,0,0,0.2)',
                      }}
                    >
                      <div style={{ display:'inline-flex',alignItems:'center',gap:'6px',padding:'4px 12px',background:`${card.accent}18`,border:`1px solid ${card.accent}33`,borderRadius:'100px',fontSize:'.68rem',fontWeight:'700',color:card.accent,letterSpacing:'.09em',textTransform:'uppercase',width:'fit-content' }}>
                        {card.badge}
                      </div>
                      <div style={{ fontSize:'clamp(1.9rem,5vw,2.5rem)',fontWeight:'800',background:`linear-gradient(130deg,${card.accent},#E8F4FF)`,WebkitBackgroundClip:'text',WebkitTextFillColor:'transparent',backgroundClip:'text',letterSpacing:'-.04em',lineHeight:'1' }}>
                        {card.metric}
                      </div>
                      <div style={{ fontSize:'.8rem',color:'var(--muted)',marginTop:'-8px' }}>{card.label}</div>
                      <div>
                        <div style={{ height:'5px',borderRadius:'3px',background:'rgba(255,255,255,.06)',overflow:'hidden' }}>
                          <div style={{ height:'100%',borderRadius:'3px',background:`linear-gradient(90deg,${card.accent},#E8F4FF)`,width:`${card.bar}%` }} />
                        </div>
                        <div style={{ fontSize:'.7rem',color:'var(--dim)',marginTop:'5px' }}>{card.note}</div>
                      </div>
                      <div style={{ height:'1px',background:'rgba(255,255,255,0.05)' }} />
                      <div style={{ display:'flex',justifyContent:'space-between',alignItems:'center' }}>
                        <span style={{ fontSize:'.73rem',color:'var(--dim)' }}>{card.s1}</span>
                        <span style={{ fontSize:'.73rem',fontWeight:'700',color:card.accent }}>{card.s2}</span>
                      </div>
                    </div>
                  );
                })}
              </div>
              <div className="deck-hint">
                <span style={{ fontSize:'.9rem' }}>↻</span> Click to flip
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

function Testimonials() {
  const [idx, setIdx] = useState(0);
  const total = TESTIMONIALS.length;
  const prev = () => setIdx(i => (i - 1 + total) % total);
  const next = () => setIdx(i => (i + 1) % total);
  useEffect(() => {
    if (total <= 1) return;
    const t = setInterval(next, 6500);
    return () => clearInterval(t);
  }, [total]);
  return (
    <section className="section hiw-bg">
      <div className="container">
        <div className="sec-head center">
          <div className="sec-label reveal">Testimonials</div>
          <h2 className="sec-h2 reveal d1">Our <span className="grad">Satisfied Clients</span></h2>
        </div>
        <div className="testi-outer reveal d2">
          <div className="testi-track" style={{ transform: `translateX(-${idx * 100}%)` }}>
            {TESTIMONIALS.map((t) => (
              <div key={t.name} className="testi-slide">
                <div className="testi-card">
                  <div className="testi-glow" />
                  <div className="testi-q">"</div>
                  <p className="testi-text">{t.quote}</p>
                  <div className="testi-footer">
                    <div className="testi-av" style={{ background: `linear-gradient(135deg,${t.color},${t.color}88)` }}>{t.initials}</div>
                    <div>
                      <div className="testi-name">{t.name}</div>
                      <div className="testi-role">{t.role}</div>
                    </div>
                    <div className="testi-stars">★★★★★</div>
                  </div>
                </div>
              </div>
            ))}
          </div>
          {total > 1 && (
            <div className="testi-nav">
              <button className="testi-btn" onClick={prev}><ChevL /></button>
              {TESTIMONIALS.map((_, i) => (
                <button key={i} className={`testi-dot${i === idx ? ' on' : ''}`} onClick={() => setIdx(i)} />
              ))}
              <button className="testi-btn" onClick={next}><ChevR /></button>
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

